    # Usamos OrderedDict para mantener el orden de inserción
    ocurrencias = OrderedDict()

    # Contar las ocurrencias de cada número
    for numero in cnt:
        if numero in ocurrencias:
            ocurrencias[numero] += 1
        else:
            ocurrencias[numero] = 1

    return ocurrencias

def main():
    # Leer la secuencia de números desde la entrada estándar
    idx = input().strip()  # Leemos la entrada y eliminamos espacios en blanco

    # Convertir la entrada en una lista de enteros
    entry = list(map(int, idx.split()))

    # Contar las ocurrencias
    prev = contar_ocurrencias(entry)

    # Imprimir el resultado
    for val, aux in prev.items():
        print(f"{val} {aux}")

if __name__ == "__main__":
    main()

