import sys
from collections import deque
from heapq import *

while 1:
    try:
        N = int(input())
    except:
        break
    index = []
    queue = deque()
    heap = []
    isStack = isQueue = isHeap = 1
    for i in range(N):
        tmp,curr = map(int, input().split())
        if tmp == 1:
            index.append(curr)
            queue.append(curr)
            heappush(heap, -curr)
        else:
            a = index.pop()
            if a != curr:
                isStack = 0
            a = queue.popleft()
            if a != curr:
                isQueue = 0
            a = -heappop(heap)
            if a != curr:
                isHeap = 0
    s = sum([isStack, isQueue, isHeap])
    if s >= 2:
        print ('not sure')
    elif s == 0:
        print ('impossible')
    else:
        if isStack:
            print ('stack')
        if isQueue:
            print ('queue')
        if isHeap:
            print ('priority queue')

