def state(value):
    # Simularemos las tres estructuras simultáneamente
    aux = []
    queue = deque()
    temp = []  # priority queue

    # Banderas para cada estructura
    cnt = True
    could_be_queue = True
    could_be_pq = True

    # Procesar cada operación
    actual_outputs = []  # Guardar las salidas reales

    for op, chunk in value:
        if op == 1:  # insertar
            aux.append(chunk)
            queue.append(chunk)
            heapq.heappush(temp, -chunk)  # Negativo para hacer max-heap
        else:  # op == 2, extraer
            actual_outputs.append(chunk)

            # Verificar stack
            if aux and aux[-1] != chunk:
                cnt = False
            if aux:
                aux.pop()

            # Verificar queue
            if queue and queue[0] != chunk:
                could_be_queue = False
            if queue:
                queue.popleft()

            # Verificar priority queue
            if temp and -heapq.heappop(temp) != chunk:
                could_be_pq = False

    # Contar cuántas estructuras coinciden
    prev = sum([cnt, could_be_queue, could_be_pq])

    if prev == 0:
        return "impossible"
    elif prev > 1:
        return "not sure"
    else:
        if cnt:
            return "stack"
        if could_be_queue:
            return "queue"
        if could_be_pq:
            return "priority queue"

