def UP_f(t_f):
    i_f = -1
    for i in range(1, len(t_f)):
        if t_f[i] == dic['<UP>']:
            t_f = t_f.replace(t_f[i::], UP_f(t_f[i::]))
        if t_f[i] == dic['</UP>']:
            i_f = i
            break
    return t_f[0:i_f + 1].replace(dic['<UP>'], '*').replace(dic['</UP>'], '*').upper() + t_f[i_f + 1::]

def DOWN_f(count):
    i_f = -1
    for i in range(1, len(count)):
        if count[i] == dic['<DOWN>']:
            count = count.replace(count[i::], UP_f(count[i::]))
        if count[i] == dic['</DOWN>']:
            i_f = i
