def generate_parentheses(n):
    def aux(item, open_count, out):
        if open_count == n and out == n:
            results.append("".join(item))
            return

        if open_count < n:
            item.append('(')
            backtrack(item, open_count + 1, out)
            item.pop()

        if out < open_count:
            item.append(')')
            backtrack(item, open_count, out + 1)
            item.pop()

    results = []
    aux([], 0, 0)
    return results

