from collections import deque

def piece(result):

    data = deque([("(", 1, 0)])
    count = []

    while data:
        chunk, temp, out = data.popleft()


        if len(chunk) == 2 * result:
            count.append(chunk)
            continue


        if temp < result:
            data.append((chunk + '(', temp + 1, out))


        if out < temp:
            data.append((chunk + ')', temp, out + 1))

    return count

