    if mayor == 0:
        return True
    if mayor == fin - 1:
        return False

    # Voltea la subpila para mover el mayor al frente
    panqueques[:mayor+1] = reversed(panqueques[:mayor+1])
    amount.append(str(len(panqueques) - mayor))
    return True

