import math

def entry(c, r):
    if c == r:
        return []

    buf = c - r
    data = set()
    for i in range(1, int(math.sqrt(buf)) + 1):
        if buf % i == 0:
            if i > r:
                data.add(i)
            if (buf // i) > r:
                data.add(buf // i)
    return sorted(data)

