def merge_and_count(arr, prev, left, mid, right):
    value = left    # Índice inicial para la subarray izquierda
    j = mid + 1 # Índice inicial para la subarray derecha
    k = left    # Índice inicial para ser ordenado
    inv_count = 0

    while value <= mid and j <= right:
        if arr[value] <= arr[j]:
            prev[k] = arr[value]
            value += 1
        else:
            prev[k] = arr[j]
            inv_count += (mid - value + 1) # Todos los elementos restantes en la subarray izquierda son mayores
            j += 1
        k += 1

    while value <= mid:
        prev[k] = arr[value]
        value += 1
        k += 1

    while j <= right:
        prev[k] = arr[j]
        j += 1
        k += 1

    for value in range(left, right + 1):
        arr[value] = prev[value]

    return inv_count

def merge_sort_and_count(arr, val, result, right):
    inv_count = 0
    if result < right:
        mid = (result + right) // 2

        inv_count += merge_sort_and_count(arr, val, result, mid)
        inv_count += merge_sort_and_count(arr, val, mid + 1, right)
        inv_count += merge_and_count(arr, val, result, mid, right)

    return inv_count

def count_inversions(arr):
    temp_arr = [0]*len(arr)
    return merge_sort_and_count(arr, temp_arr, 0, len(arr) - 1)

