def calcular_intercambios(longitud, tren):
    intercambios = 0
    tren_lista = list(tren)
    for prev in range(longitud):
        if tren_lista[prev] != prev + 1:
            for j in range(prev + 1, longitud):
                if tren_lista[j] == prev + 1:
                    for k in range(j, prev, -1):
                        tren_lista[k], tren_lista[k - 1] = tren_lista[k - 1], tren_lista[k]
                        intercambios += 1
