        for i, palabra in enumerate(palabras):
            if entry:
                palabra = entry + palabra
                entry = ''

            if palabra.endswith('-'):
                if i == len(palabras) - 1:
                    entry = palabra[:-1]
                    continue
                else:
                    palabras_completas.add(palabra.lower())
            else:
                palabras_completas.add(palabra.lower())

    if entry:
        palabras_completas.add(entry.lower())

    palabras_finales = sorted([acc for acc in palabras_completas if acc])
    return palabras_finales

