def entry():
    count = set()  # Usamos un set para almacenar palabras únicas
    res = ""  # Para manejar palabras que continúan en la siguiente línea

    try:
        while True:
            try:
                data = input().strip()

                # Si la línea está vacía, procesamos la palabra pendiente si existe
                if not data and res:
                    count.add(res.lower())
                    res = ""
                    continue

                # Dividir la línea en palabras
                aux = data.split()

                if not aux:
                    continue

                # Procesar cada palabra en la línea
                for prev, piece in enumerate(aux):
                    # Eliminar puntuación al final de la palabra
                    piece = piece.rstrip('.,')

                    # Caso 1: Tenemos una palabra pendiente
                    if res:
                        if piece.endswith('-'):
                            # La palabra sigue continuando
                            res += piece[:-1]
                        else:
                            # La palabra termina aquí
                            item = res + piece
                            count.add(item.lower())
                            res = ""

                    # Caso 2: Nueva palabra que puede continuar
                    elif piece.endswith('-'):
                        if prev == len(aux) - 1:  # Si es la última palabra de la línea
                            res = piece[:-1]
                        else:
                            # Es un guión que forma parte de la palabra
                            count.add(piece.lower())

                    # Caso 3: Palabra normal
                    else:
                        # Verificar si es una palabra válida (contiene letras)
                        if any(buf.isalpha() for buf in piece):
                            count.add(piece.lower())

            except EOFError:
                # Si hay una palabra pendiente al final del archivo, la agregamos
                if res:
                    count.add(res.lower())
                break

        # Convertir guiones de continuación en el medio de las palabras
        tmp = set()
        for piece in count:
            if '-' in piece and not piece.endswith('-'):
                # Agregar tanto la versión con guión como sin guión
                tmp.add(piece)
                tmp.add(piece.replace('-', ''))
            else:
                tmp.add(piece)

        # Ordenar e imprimir las palabras
        for piece in sorted(tmp):
            print(piece)

    except EOFError:
        pass

