import sys
import re
def procesar_texto():
    palabras = set()
    buf = ""
    for linea in sys.stdin:
        linea = linea.strip().lower()  
        if linea.endswith('-'):
            buf += linea[:-1]  
        else:
            buf += linea
            for arr in re.findall(r'\b[a-z-]+\b', buf):
                palabras.add(arr)
            buf = ""  
    palabras_ordenadas = sorted(palabras)    
    for arr in palabras_ordenadas:
        print(arr)
if __name__ == "__main__":
    procesar_texto()

