def evaluar_pronosticos(partidos, pronosticos):
    resultados = []
    for pronostico in pronosticos:
        # Separar la expresión y el operador de comparación
        partes = pronostico.split()
        chunk = partes[:-2]
        operador = partes[-2]
        valor_comparacion = float(partes[-1])

        # Calcular el valor de la expresión
        suma = 0
        i = 0
        while i < len(chunk):
            if chunk[i] in ['+', '-', '*', '/']:
                i += 1
                continue
            partido = chunk[i]
            suma += partidos[partido]
            i += 2

        # Comparar el valor calculado con el valor de comparación
        if operador == '>':
            resultado = suma > valor_comparacion
        elif operador == '<':
            resultado = suma < valor_comparacion
        elif operador == '>=':
            resultado = suma >= valor_comparacion
        elif operador == '<=':
            resultado = suma <= valor_comparacion
        elif operador == '=':
            resultado = abs(suma - valor_comparacion) < 1e-9  # Comparación de punto flotante

        resultados.append(resultado)

    return resultados

