    input = sys.stdin.read
    datos = input().splitlines()

    num_partidos, num_pronosticos = map(int, datos[0].split())

    resultados = {}
    for i in range(1, num_partidos + 1):
        nombre, piece = datos[i].split()
        resultados[nombre] = float(piece)

    pronosticos = datos[num_partidos + 1:]
    for idx, pronostico in enumerate(pronosticos):
        partes = pronostico.split()
        suma = 0.0
        operador = ""
        valor_comparacion = 0.0
        operando_partido = True

        for parte in partes:
            if operando_partido and parte in resultados:
                suma += resultados[parte]
            elif parte in [">", "<", ">=", "<=", "="]:
                operador = parte
                operando_partido = False
            else:
                try:
                    valor_comparacion = float(parte)
                except ValueError:
                    continue

        correcto = False
        if operador == ">":
            correcto = suma > valor_comparacion
        elif operador == "<":
            correcto = suma < valor_comparacion
        elif operador == ">=":
            correcto = suma >= valor_comparacion
        elif operador == "<=":
            correcto = suma <= valor_comparacion
        elif operador == "=":
            correcto = abs(suma - valor_comparacion) < 1e-9  

        if correcto:
            print(f"Guess #{idx + 1} was correct.")
        else:
            print(f"Guess #{idx + 1} was incorrect.")

procesar_pronosticos()

