def evaluar_pronostico(resultados, partidos, operador, valor_comparacion):
    suma = sum(resultados[partido] for partido in partidos)
    EPSILON = 0.0001

    if operador == ">":
        return suma > valor_comparacion + EPSILON
    elif operador == "<":
        return suma < valor_comparacion - EPSILON
    elif operador == ">=":
        return suma >= valor_comparacion - EPSILON
    elif operador == "<=":
        return suma <= valor_comparacion + EPSILON
    elif operador == "=":
        return abs(suma - valor_comparacion) < EPSILON
    return False

