def elem(acc, item, op):
    state = 1e-9  # Small value to account for floating-point imprecision
    if op == '>':
        return acc > item + state
    elif op == '<':
        return acc < item - state
    elif op == '>=':
        return acc >= item - state
    elif op == '<=':
        return acc <= item + state
    elif op == '=':
        return abs(acc - item) < state

