def compare_float(a, b, op):
    epsilon = 1e-9  # Small value to account for floating-point imprecision
    if op == '>':
        return a > b + epsilon
    elif op == '<':
        return a < b - epsilon
    elif op == '>=':
        return a >= b - epsilon
    elif op == '<=':
        return a <= b + epsilon
    elif op == '=':
        return abs(a - b) < epsilon

