def compare_float(num, b, op):
    epsilon = 1e-9
    if op == '>':
        return num > b + epsilon
    elif op == '<':
        return num < b - epsilon
    elif op == '>=':
        return num >= b - epsilon
    elif op == '<=':
        return num <= b + epsilon
    elif op == '=':
        return abs(num - b) <= epsilon

