    operator = None
    count = None

    for token in tokens:
        if token in party_percentages:
            current_sum += party_percentages[token]
        elif token == '+':
            continue  # Sumar explícitamente, ya es manejado
        elif token in {'>=', '<=', '=', '>', '<'}:
            operator = token
        elif token.isdigit():
            count = int(token)

    # Evaluar la expresión
    if operator == '>':
        return current_sum > count
    elif operator == '<':
        return current_sum < count
    elif operator == '>=':
        return current_sum >= count
    elif operator == '<=':
        return current_sum <= count
    elif operator == '=':
        return abs(current_sum - count) < 1e-6
    else:
        return False

