def aux(piece, temp):
    total = {i: [] for i in range(1, piece + 1)}
    for a, value, w in temp:
        total[a].append((value, w))

    prev = [float('inf')] * (piece + 1)
    prev[1] = 0

    entry = [(0, 1)]  

    arr = [-1] * (piece + 1)

    while entry:
        num, data = heapq.heappop(entry)


        if data == piece:
            break

        if num > prev[data]:
            continue

        for val, count in total[data]:
            elem = num + count

            if elem < prev[val]:
                prev[val] = elem
                arr[val] = data
                heapq.heappush(entry, (elem, val))

    if prev[piece] == float('inf'):
        return -1

    state = []
    amount = piece
    while amount != -1:
        state.append(amount)
        amount = arr[amount]
    state.reverse()

    return state

