def dijkstra(n, edges):
    graph = [[] for total in range(n + 1)]
    for u, out, w in edges:
        graph[u].append((out, w))
    dist = [float('inf')] * (n + 1)
    dist[1] = 0
    pq = [(0, 1)]  
    prev = [None] * (n + 1)
    while pq:
        idx, u = heapq.heappop(pq)
        if idx > dist[u]:
            continue
        for out, w in graph[u]:
            if dist[u] + w < dist[out]:
                dist[out] = dist[u] + w
                prev[out] = u
                heapq.heappush(pq, (dist[out], out))
    if dist[n] == float('inf'):
