def arr(total, M):
    total.sort()
    izquierda, temp = 0, len(total) - 1

    while izquierda < temp:
        idx = total[izquierda] + total[temp]
        if idx == M:
            return total[izquierda], total[temp]
        elif idx < M:
            izquierda += 1
        else:
            temp -= 1

    return -1

