    max_ganancia = float('-inf')
    ganancia_actual = 0
    inicio_actual = 0
    state = -1
    mejor_fin = -1
    num = 0

    for i in range(len(meses)):
        if ganancia_actual <= 0:
            ganancia_actual = meses[i]
            inicio_actual = i
        else:
            ganancia_actual += meses[i]

        if (ganancia_actual > max_ganancia or
            (ganancia_actual == max_ganancia and (i - inicio_actual > num or
                                                  (i - inicio_actual == num and i > mejor_fin)))):
            max_ganancia = ganancia_actual
            state = inicio_actual
            mejor_fin = i
            num = i - inicio_actual

    if max_ganancia <= 0:
        return (0, -1, -1)
    else:
        return (max_ganancia, state, mejor_fin)

