def value(entry):
    num = float('-inf')
    amount = 0
    acc = 0
    idx = -1
    curr = -1
    index = 0

    for count in range(len(entry)):
        if amount <= 0:
            amount = entry[count]
            acc = count
        else:
            amount += entry[count]

        if (amount > num or
            (amount == num and (count - acc > index or (count - acc == index and count > curr)))):
            num = amount
            idx = acc
            curr = count
            index = count - acc

    if num <= 0:
        return (0, -1, -1)
    else:
        return (num, idx, curr)

