def format_polynomial(coefficients):
    index = []
    for i, coeff in enumerate(coefficients):
        degree = len(coefficients) - 1 - i
        if coeff != 0:
            if degree == 0:
                index.append(f"{coeff}")
            elif degree == 1:
                index.append(f"{'' if coeff == 1 else '-' if coeff == -1 else coeff}x")
            else:
                index.append(f"{'' if coeff == 1 else '-' if coeff == -1 else coeff}x^{degree}")

    if not index:
        return "0"

    formatted_polynomial = index[0]
    for prev in index[1:]:
        if prev.startswith('-'):
            formatted_polynomial += f" {prev}"
        else:
            formatted_polynomial += f" + {prev}"

    return formatted_polynomial.replace(' -', ' - ')  

