    res = [[0] * n for _ in range(amount)]
    for j in range(amount):
        res[0][j] = first_row[j]
    for total in range(amount):
        res[total][0] = first_col[total]
    for total in range(1, amount):
        for j in range(1, amount):
            res[total][j] = res[total][j-1] + res[total-1][j] + res[total-1][j-1]
    return res[amount-1][amount-1]
