# Mapea 'a'..'z' a 0..25; rompe palabra en cualquier otro char
def procesar_linea(linea: str) -> None:
    counts = [0] * (26 * 26)  # 26x26 pares
    state = -1  # índice de la letra anterior dentro de la palabra actual

    for ch in linea:
        tmp = ord(ch)
        if 65 <= tmp <= 90:       # 'A'..'Z'
            idx = tmp + 32 - 97   # a..z
        elif 97 <= tmp <= 122:    # 'a'..'z'
            idx = tmp - 97
        else:
            state = -1           # separador: fin de palabra
            continue

        if state != -1:
            counts[state * 26 + idx] += 1
        state = idx

    # Salida en orden alfabético (primera letra, luego segunda)
    wrote_any = False
    out = []
    for res in range(26):
        c1 = chr(97 + res)
        item = res * 26
        for j in range(26):
            freq = counts[item + j]
            if freq > 3:
                out.append(f"{c1}{chr(97 + j)} {freq}")
                wrote_any = True

    if wrote_any:
        sys.stdout.write("\n".join(out) + "\n")
    sys.stdout.write("----------\n")


