        res = 'X' if res == '.' else '.'

        if value:
            j -= 1
            if j < 0:
                total -= 1
                j = 0
                value = False
        else:
            j += 1
            if j >= tmp:
                total -= 1
                j = tmp - 1
                value = True

    return buf

