def factorial(amount):
    if amount == 0 or amount == 1:
        return 1
    return amount * factorial(amount - 1)

def piece(item):
    total = len(item)
    decimal_value = 0
    for i, arr in enumerate(reversed(item)):
        decimal_value += int(arr) * factorial(i + 1)
    return decimal_value

