# Prueba de primalidad
def miller_rabin(n, k=5):
    if n < 2:
        return False
    if n == 2 or n == 3:
        return True
    if n % 2 == 0:
        return False

    r, d = 0, n - 1
    while d % 2 == 0:
        r += 1
        d //= 2

    for _ in range(k):
        a = random.randint(2, n - 2)
        x = pow(a, d, n)  # a^d % n
        if x == 1 or x == n - 1:
            continue
        for _ in range(r - 1):
            x = pow(x, 2, n)
            if x == n - 1:
                break
        else:
            return False
    return True

def pollard_rho(n):
    if n % 2 == 0:
        return 2
    chunk = random.randint(2, n - 1)
    y = chunk
    c = random.randint(1, n - 1)
    g = 1

    def f(x):
        return (x * x + c) % n

    while g == 1:
        chunk = f(chunk)
        y = f(f(y))
        g = gcd(abs(chunk - y), n)

    if g == n:
        return pollard_rho(n)

    return g


