def pollards_rho(value):
    if value % 2 == 0:
        return 2
    x = random.randint(2, value - 1)
    y = x
    c = random.randint(1, value - 1)
    d = 1
    while d == 1:
        x = (x * x + c) % value
        y = (y * y + c) % value
        y = (y * y + c) % value
        d = gcd(abs(x - y), value)
        if d == value:
            return pollards_rho(value)
    return d

