def sieve_of_eratosthenes(max_num):
    is_prime = [True] * (max_num + 1)
    p = 2
    while (p * p <= max_num):
        if is_prime[p]:
            for chunk in range(p * p, max_num + 1, p):
                is_prime[chunk] = False
        p += 1
    return [p for p in range(2, max_num + 1) if is_prime[p]]

def prime_factors_sum(curr, primes):
    factor_sum = 0
    original_n = curr
    for prime in primes:
        if prime * prime > curr:
            break
        if curr % prime == 0:
            factor_sum += prime
            while curr % prime == 0:
                curr //= prime
    if curr > 1:  # If there's a prime factor greater than sqrt(n)
        factor_sum += curr
    return factor_sum

def find_ruth_aaron_pairs(a, value, primes):
    pairs = []
    prime_sum_cache = {}

    for n in range(a, value):
        if n not in prime_sum_cache:
            prime_sum_cache[n] = prime_factors_sum(n, primes)
        if (n + 1) not in prime_sum_cache:
            prime_sum_cache[n + 1] = prime_factors_sum(n + 1, primes)

        if prime_sum_cache[n] == prime_sum_cache[n + 1]:
            pairs.append((n, n + 1))

    return pairs

