def calculate_wait_time(piece, amount):
    wait_time = 0
    while piece:
        current_job = piece.pop(0)  # Get the first job

        # Check if there's a higher priority job in the remaining queue
        cnt = any(job > current_job for job in piece)

        if cnt:
            piece.append(current_job)  # Move current job to the back
        else:
            wait_time += 1  # Increment waiting time
            if amount == 0:
                return wait_time  # Your job is done

        amount -= 1  # Update your position in the queue
        if amount < 0:
            amount = len(piece) - 1  # Wrap around if moved to the back

