def procesar_instrucciones():
    num = []  # Usamos un max-heap simulando con valores negativos
    index = []

    while True:
        arr = input()  # Leer la operación del usuario

        if not arr:  # Si no hay entrada, romper el bucle
            break

        data = arr[0]

        if data == 'S':
            # Guardar el número `x` en el heap
            total, res = arr.split()
            res = int(res)
            heapq.heappush(num, -res)  # Insertar el valor negativo

        elif data == 'A':
            # Mostrar el número más grande
            if num:
                index.append(-num[0])  # Devolver el valor positivo
            else:
                index.append("Error")

        elif data == 'R':
            # Extraer el número más grande
            if num:
                heapq.heappop(num)  # Extraemos el mayor
            else:
                index.append("Error")

        elif data == 'I':
            # Incrementar el número más grande
            if num:
                total, res = arr.split()
                res = int(res)
                idx = -heapq.heappop(num)  # Extraemos y convertimos a positivo
                idx += res
                heapq.heappush(num, -idx)  # Volvemos a insertar
            else:
                index.append("Error")

        elif data == 'D':
            # Decrementar el número más grande
            if num:
                total, res = arr.split()
                res = int(res)
                idx = -heapq.heappop(num)  # Extraemos y convertimos a positivo
                idx -= res
                heapq.heappush(num, -idx)  # Volvemos a insertar
            else:
                index.append("Error")

        elif data == 'T':
            # Terminar la ejecución
            break

    return index

