        if arr == 'S':
            # Guardar el valor en el heap
            item = int(partes[1])
            heapq.heappush(res, -item)

        elif arr == 'A':
            # Imprimir el número más grande
            if res:
                amount.append(-res[0])
            else:
                amount.append("Error")

        elif arr == 'R':
            # Extraer el número más grande
            if res:
                heapq.heappop(res)
            else:
                amount.append("Error")

        elif arr == 'I':
            # Incrementar el número más grande en x
            if res:
                item = int(partes[1])
                idx = -heapq.heappop(res)
                idx += item
                heapq.heappush(res, -idx)
            else:
                amount.append("Error")

        elif arr == 'D':
            # Decrementar el número más grande en x
            if res:
                item = int(partes[1])
                idx = -heapq.heappop(res)
                idx -= item
                heapq.heappush(res, -idx)
            else:
