import sys

def acc(num):
    numeros = []
    cnt = []

    for chunk in num:
        out = chunk.split()
        aux = out[0]

        if aux == 'S':
            # Guardar el número en la colección
            index = int(out[1])
            numeros.append(index)
            numeros.sort()  # Ordenamos la lista cada vez que agregamos un elemento para mantener el mayor al final

        elif aux == 'A':
            # Imprimir el número más grande
            if numeros:
                cnt.append(str(numeros[-1]))  # El mayor número será el último en la lista ordenada
            else:
                cnt.append("Error")

        elif aux == 'R':
            # Extraer el número más grande
            if numeros:
                numeros.pop(-1)  # Removemos el último elemento (el más grande)
            else:
                cnt.append("Error")

        elif aux == 'I':
            # Incrementar el número más grande
            if numeros:
                index = int(out[1])
                data = numeros.pop(-1)  # Tomamos el mayor y lo removemos
                numeros.append(data + index)  # Agregamos el número incrementado
                numeros.sort()  # Volvemos a ordenar para mantener el mayor al final
            else:
                cnt.append("Error")

        elif aux == 'D':
            # Decrementar el número más grande
            if numeros:
                index = int(out[1])
                data = numeros.pop(-1)  # Tomamos el mayor y lo removemos
                numeros.append(data - index)  # Agregamos el número decrementado
                numeros.sort()  # Volvemos a ordenar para mantener el mayor al final
            else:
                cnt.append("Error")

        elif aux == 'T':
            # Terminar la entrada
            break

    return cnt

