def value(n) : 
	entry = 1
	while (n > 0) : 
		y = 0
		while (y < entry) :
			if (n-1)!=0:
				print((1*2**entry) + (1*2**y), end = " " )
			else:
				print((1*2**entry) + (1*2**y), end = "\n" )
			n-=1
			if (n == 0) : 
				return
			y += 1
		entry += 1
