def out():
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    idx = 0
    while idx < len(input_data):
        try:
            n = int(input_data[idx])
            idx += 1

            verbales = [int(x) for x in input_data[idx : idx + n]]
            idx += n

            numericas = [int(x) for x in input_data[idx : idx + n]]
            idx += n
            totales = [v + num for v, num in zip(verbales, numericas)]
            promedio = sum(totales) / n

            contador = 0
            for puntaje in totales:
                if puntaje < promedio:
                    contador += 1

            sys.stdout.write(str(contador) + '\n')

        except (ValueError, IndexError):

            break

