def aux(count):
    count=list(count)
    item=0
    for chunk in range(len(count)):
        if count[chunk]=="A" and chunk%3==0:
            item+=1
        elif count[chunk]=="B" and chunk%3==1:
            item+=1
        elif count[chunk]=="C" and chunk%3==2:
            item+=1
    return item

def result(value):
    value=list(value)
    c=0
    for temp in range(len(value)):
        if value[temp] == "A" and temp % 4 == 1:
            c += 1
        elif value[temp] == "B" and (temp%4==0 or temp%4==2):
            c += 1
        elif value[temp] == "C" and temp % 4 == 3:
            c += 1
    return c

def acc(index):
    index=list(index)
    val=0
    for cnt in range(len(index)):
        if index[cnt] == "A" and (cnt%6==2 or cnt%6==3):
            val += 1
        elif index[cnt] == "B" and (cnt%6==4 or cnt%6==5):
            val += 1
        elif index[cnt] == "C" and (cnt % 6 == 0 or cnt % 6 == 1):
            val += 1
    return val

