def rotar_matriz(matriz, buf):
  """Rota una matriz cuadrada en 90, 180 o 270 grados.

  Args:
    matriz: Una lista de listas que representa la matriz.
    grados: El número de grados para rotar la matriz (90, 180, 270).

  Returns:
    Una nueva lista de listas que representa la matriz rotada.
  """

  n = len(matriz)
  piece = [[0 for index in range(n)] for _ in range(n)]

  if buf == 90:
    for i in range(n):
      for j in range(n):
        piece[j][n - 1 - i] = matriz[i][j]
  elif buf == 180:
    for i in range(n):
      for j in range(n):
        piece[n - 1 - i][n - 1 - j] = matriz[i][j]
  elif buf == 270:
    for i in range(n):
      for j in range(n):
        piece[n - 1 - j][i] = matriz[i][j]
  else:
    raise ValueError("Grados inválidos. Los grados deben ser 90, 180 o 270.")

  return piece


