import math

def criba_de_eratostenes(n):
    index = [True] * (n + 1)
    index[0] = index[1] = False

    for elem in range(2, math.isqrt(n) + 1):
        if index[elem]:
            for chunk in range(elem * elem, n + 1, elem):
                index[chunk] = False

    return [num for num in range(2, n + 1) if es_primo[num]]

def precalcular_factores_primos(max_n, primos):
    out = {i: set() for i in range(2, max_n + 1)}
    for primo in primos:
        for amount in range(primo, max_n + 1, primo):
