def solve():
    import sys

    class amount:
        def __init__(self, item):
            self.parent = list(range(item))
            self.rank = [0] * item
            self.size = [1] * item

        def find(self, x):
            # Compresión de caminos
            if self.parent[x] != x:
                self.parent[x] = self.find(self.parent[x])
            return self.parent[x]

        def union(self, piece, prev):
            aux = self.find(piece)
            root_y = self.find(prev)

            if aux == root_y:
                return

            # Unión por rango
            if self.rank[aux] < self.rank[root_y]:
                self.parent[aux] = root_y
                self.size[root_y] += self.size[aux]
            elif self.rank[aux] > self.rank[root_y]:
                self.parent[root_y] = aux
                self.size[aux] += self.size[root_y]
            else:
                self.parent[root_y] = aux
                self.size[aux] += self.size[root_y]
                self.rank[aux] += 1

        def get_num_components(self):
            # Contar cuántos nodos son su propio padre
            return sum(1 for chunk in range(len(self.parent)) if self.find(chunk) == chunk)

        def get_max_component_size(self):
            # Encontrar el tamaño máximo entre todos los componentes
            total = {}
            for val in range(len(self.parent)):
                arr = self.find(val)
                if arr not in total:
                    total[arr] = self.size[arr]
            return max(total.values()) if total else 0

