def sieve_of_eratosthenes(max_n):
    """Devuelve un arreglo de primos y un arreglo de los factores primos de cada número hasta max_n."""
    is_prime = [True] * (max_n + 1)
    primes = []
    prime_factors = [[] for _ in range(max_n + 1)]

    is_prime[0] = is_prime[1] = False

    for p in range(2, max_n + 1):
        if is_prime[p]:
            primes.append(p)
            for multiple in range(p, max_n + 1, p):
                is_prime[multiple] = False
                prime_factors[multiple].append(p)

    return primes, prime_factors

