def generar_primos(hasta):
    # Aproximación generosa para asegurarnos de cubrir suficientes primos
    limite = hasta * int(math.log(hasta) + math.log(math.log(hasta))) + 500
    es_primo = [True] * (limite + 1)
    es_primo[0] = es_primo[1] = False  # 0 y 1 no son primos

    for i in range(2, int(math.sqrt(limite)) + 1):
        if es_primo[i]:
            for j in range(i * i, limite + 1, i):
                es_primo[j] = False

    # Generar lista de primos
    primos = [i for i in range(2, limite + 1) if es_primo[i]]

    # Asegurarse de tener suficientes primos para las posiciones pedidas
    return primos[:hasta + 1]

