def sieve(limit):
    """
    Calcula y retorna una lista de números primos hasta 'limit' (inclusive)
    usando la Criba de Eratóstenes.
    """
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(limit**0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, limit + 1, i):
                is_prime[j] = False
    primes = [i for i, prime in enumerate(is_prime) if prime]
    return primes

def digit_sum(n):
    s = 0
    while n:
        s += n % 10
        n //= 10
    return s

def generate_primes_by_index(max_index):

    upper_bound = 1600000
    primes_list = sieve(upper_bound)
    if len(primes_list) < max_index + 1:
        while len(primes_list) < max_index + 1:
            upper_bound *= 2
            primes_list = sieve(upper_bound)
    return primes_list

