def find_subsets_with_sum(data, target_sum):
    def backtrack(index, current_sum, subset):
        if index == len(numbers):
            return 1 if current_sum == target_sum else 0

        count = backtrack(index + 1, current_sum, subset)
        subset.append(numbers[index])
        count += backtrack(index + 1, current_sum + numbers[index], subset)
        subset.pop()

        return count

    return backtrack(0, 0, [])

