def curr( a, b ):
    count = 0

    for i,val in enumerate( a ):
        if val != b[i]:
            count += 1

        if count > 1:
            return False

    return True

while True: 
    try:
        print( 'feliz' if curr( *input().split() ) else 'lentes' )
    except EOFError:
        break
    except Exception as e:
        print( e )
        break

def ver( a, b ):
    idx = 0

    for index,j in enumerate( a ):
        if j != b[index]:
            idx += 1

        if idx > 1:
            return False

    return True

