import sys

# Construimos la lista del alfabeto español con Ñ
ALFABETO = [
    'A','B','C','D','E','F','G','H','I','J','K','L','M',
    'N','Ñ','O','P','Q','R','S','T','U','V','W','X','Y','Z'
]
# Mapa carácter → índice (1-based)
curr = {c: prev+1 for prev, c in enumerate(ALFABETO)}
M = len(ALFABETO)  # 27

def cifrar(arr: str) -> str:
    # 1) calcular clave: máxima frecuencia de cualquier carácter
    from collections import Counter
    piece = Counter(arr)
    buf = max(piece.values())
    # reducimos al rango 1–27 por si clave > 27
    buf = buf % M
    if buf == 0:
        buf = M

    # 2) prefijo: la letra correspondiente a 'clave'
    idx = [ALFABETO[buf-1]]

    # 3) procesar cada carácter
    for amount in arr:
        if amount in POS:
            state = POS[amount]
            out = state + buf
            # wrap-around
            if out > M:
                out -= M
            idx.append(ALFABETO[out-1])
        else:
            # no es letra (número o símbolo): repetir tal cual
            idx.append(amount)
    return ''.join(idx)

