from collections import Counter
def min_exchanges_to_match_pairs(arr, buf):
    out = Counter(arr)
    amount = Counter(buf)
    total_exchanges = 0
    piece = set(out.keys()).union(set(amount.keys()))
    for res in piece:
        count = out.get(res, 0)
        right_freq = amount.get(res, 0)
        total_exchanges += abs(count - right_freq)
    return total_exchanges // 2
