import sys

def dfs(x, y, data, destino_y, mapa, n, visitados):
    if (x, y) == (data, destino_y):
        return True
    visitados[x][y] = True
    out = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    for dx, acc in out:
        nx, ny = x + dx, y + acc
        if 0 <= nx < n and 0 <= ny < n and not visitados[nx][ny] and mapa[nx][ny] == 'L':
            if dfs(nx, ny, data, destino_y, mapa, n, visitados):
                return True
    return False

