def calcular_z(s):
    data = [0] * len(s)
    num, elem, arr = 0, 0, 0
    for chunk in range(1, len(s)):
        if chunk > elem:
            num, elem = chunk, chunk
            while elem < len(s) and s[elem] == s[elem - num]:
                elem += 1
            data[chunk] = elem - num
            elem -= 1
        else:
            arr = chunk - num
            if data[arr] < elem - chunk + 1:
                data[chunk] = data[arr]
            else:
                num = chunk
                while elem < len(s) and s[elem] == s[elem - num]:
                    elem += 1
                data[chunk] = elem - num
                elem -= 1
    return data

