        if elem > r:
            out, r = elem, elem
            while r < len(s) and s[r] == s[r - out]:
                r += 1
            z[elem] = r - out
            r -= 1
        else:
            tmp = elem - out
            if z[tmp] < r - elem + 1:
                z[elem] = z[tmp]
            else:
                out = elem
                while r < len(s) and s[r] == s[r - out]:
                    r += 1
                z[elem] = r - out
