import sys

def count_occurrences(num, res):
    ans = 0
    i = 0
    tam = len(num)
    while i < len(num):
        if (tam - i) >= len(res):
            curr = True
            for j in range(len(res)):
                if num[i + j] != res[j]:
                    curr = False
            if curr:
                ans += 1
                i += len(res)
            else:
                i += 1
        else:
            i += 1
    return ans

