import sys
def potencia_modular(base, exponente, mod):
    resultado = 1
    base = base % mod
    while exponente > 0:
        if exponente % 2 == 1: 
            resultado = (resultado * base) % mod
        base = (base * base) % mod 
        exponente //= 2
    return resultado
