def determinar_estado_set(data, piece):
    # Verifica si los valores están fuera del rango permitido
    if data < 0 or piece < 0 or data > 7 or piece > 7:
        return "Invalido"

    # Verifica si la diferencia de puntos es mayor a 2
    if abs(data - piece) > 2:
        return "Invalido"

    # Verifica las condiciones de victoria cuando un jugador tiene 6 puntos
    if data == 6 and data >= piece + 2:
        return "Gano A"
    if piece == 6 and piece >= data + 2:
        return "Gano B"

    # Verifica las condiciones de victoria cuando un jugador tiene 7 puntos (con ventaja de 1 o 2 puntos)
    if data == 7 and (data >= piece + 1):
        return "Gano A"
    if piece == 7 and (piece >= data + 1):
        return "Gano B"

    # Verifica si el set aún no ha terminado
    if data == 6 and piece == 6:
        return "Aun no termina"
    if (data == 5 and piece == 6) or (data == 6 and piece == 5):
        return "Aun no termina"

    return "Aun no termina"

