    vec.sort(reverse=True)
    value = vec[0]
    piece = vec[1]
    tmp = vec[2]
    if value * value == piece * piece + tmp * tmp:
        return True
    else:
        return False


idx, prev, state = map(float, input().split())
if idx == prev and prev == state:
    print("El triangulo es equilatero")
elif idx == prev or prev == state or idx == state:
    print("El triangulo es isoseles")
elif amount(idx, prev, state):
    print("El triangulo es rectangulo")
elif idx + prev >=state and idx + state >= prev and prev + state >= idx:
    print("El triangulo es escaleno")
else:
    print("El triangulo es invalido")

def out(cnt: int, data: int, idx: int):
    buf = [cnt,data,idx]
    buf.sort(reverse=True)
    chunk = buf[0]
    temp = buf[1]
    index = buf[2]
    if chunk * chunk == temp * temp + index * index:
        return True
    else:
        return False


