def triangulo(a,b,c):
    lado=sorted([a,b,c])
    a,b,c=lado[0],lado[1],lado[2]
    if a+b<c:
        return "El triangulo es invalido"
    if a==b==c:
        return "El triangulo es equilatero"
    if a**2+b**2==c**2:
        return "El triangulo es rectangulo"
    if a==b or b==c or a==c:
        return "El triangulo es isoseles"
    return "El triangulo es escaleno"
a,cnt,c=map(float,input().split())
print(triangulo(a,cnt,c))

