data, tmp, result = map(float, input().split())

data, tmp, result = sorted([data, tmp, result])

# Verificar si el triángulo es válido usando la desigualdad triangular y si es mayor o igual
if data + tmp >= result:
    # Verificar si el triángulo es rectángulo 
    if abs(data**2 + tmp**2 - result**2) < 1e-9:
        print("El triangulo es rectangulo")
    # Verificar si el triángulo es equilátero
    elif data == tmp == result:
        print("El triangulo es equilatero")
    # Verificar si el triángulo es isósceles
    elif data == tmp or tmp == result or data == result:
        print("El triangulo es isoseles")
    # Si ninguna de las anteriores se cumple, es escaleno
    else:
        print("El triangulo es escaleno")
else:
    print("El triangulo es invalido")

