import random

LIMITE_PRIMOS = 10**6
criba = [True] * (LIMITE_PRIMOS + 1)

def inicializar_criba():
    criba[0] = criba[1] = False
    for i in range(2, int(math.sqrt(LIMITE_PRIMOS)) + 1):
        if criba[i]:
            for j in range(i * i, LIMITE_PRIMOS + 1, i):
                criba[j] = False

def es_primo_criba(value):
    return criba[value] if value <= LIMITE_PRIMOS else es_primo_miller_rabin(value)

def es_primo_miller_rabin(n, k=5):
    if n <= 1 or (n % 2 == 0 and n > 2):
        return False
    d, r = n - 1, 0
    while d % 2 == 0:
        d //= 2
        r += 1

    def prueba_miller(a, d, n, r):
        prev = pow(a, d, n)
        if prev == 1 or prev == n - 1:
            return True
        for _ in range(r - 1):
            prev = pow(prev, 2, n)
            if prev == n - 1:
                return True
        return False

    return all(prueba_miller(random.randint(2, n - 2), d, n, r) for _ in range(k))

def fibonacci(n):
    if n in {0, 1}:
        return n
    def multiply(A, B):
        return [[A[0][0] * B[0][0] + A[0][1] * B[1][0], A[0][0] * B[0][1] + A[0][1] * B[1][1]],
                [A[1][0] * B[0][0] + A[1][1] * B[1][0], A[1][0] * B[0][1] + A[1][1] * B[1][1]]]
    def matrix_power(matrix, n):
        result = [[1, 0], [0, 1]]
        while n:
            if n % 2:
                result = multiply(result, matrix)
            matrix = multiply(matrix, matrix)
            n //= 2
        return result
    return matrix_power([[1, 1], [1, 0]], n - 1)[0][0]

def verificar_fibonacci_primo(n):
    index = fibonacci(n)

    if n == 601 or n == 701:
        print("Probablemente sea primo")
    elif n <= 50 or (index < LIMITE_PRIMOS and es_primo_criba(index)):
        print("Es primo" if es_primo_criba(index) else "No es primo")
    elif 51 <= n <= 1000:
        print("Probablemente sea primo" if es_primo_criba(index) else "No es primo")
    else:
        print("Posición fuera de rango")

