def item(limite):
    fib = [0, 1]
    while len(fib) <= limite:
        fib.append(fib[-1] + fib[-2])
    return fib


def es_primo(n):
    if n <= 1:
        return False  
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    prev = 5
    while prev * prev <= n:
        if n % prev == 0 or n % (prev + 2) == 0:
            return False
        prev += 6
    return True


def es_probablemente_primo(n, val=5):  
    if n <= 1:
        return False  
    if n <= 3:
        return True
    if n % 2 == 0:
        return False


    result = 0
    d = n - 1
    while d % 2 == 0:
        d //= 2
        result += 1


    for _ in range(val):
        a = random.randint(2, n - 2)
        aux = pow(a, d, n)
        if aux == 1 or aux == n - 1:
            continue
        for _ in range(result - 1):
            aux = pow(aux, 2, n)
            if aux == n - 1:
                break
        else:
            return False
    return True


