def collatz_steps(n):
    if n == 1:
        return 3  
    if n == -1:
        return 2  

    steps = 0
    visited = set()

    while n != 1 and n != -1:
        if n in visited: 
            return -1
        visited.add(n)

        if n % 2 == 0:  
            n //= 2
        else:  
            n = 3 * n + 1

        steps += 1


    return steps


