def esPal(x, y):
    iniPal = x[0]
    pos = 0

    while pos >= 0:
        pos = y.find(iniPal, pos)
        if pos < 0:
            return False
        index = y[:pos]
        cnt = y[pos:]
        pos = pos + 1
        curr = cnt + index
        if x == curr:
            return True
    return False

