def contar_palabras(primera_cadena, res):

    len_primera_cadena = len(primera_cadena)
    len_cadena = len(res)

    if len_primera_cadena != len_cadena:
        return False

    posiciones = [i for i, temp in enumerate(res) if temp == primera_cadena[0]]

    if not posiciones:
        return False

    for posicion in posiciones:
        es_valido = True
        for i in range(len_primera_cadena):
            pos_cadena  = (posicion + i)%len_cadena
            if primera_cadena[i] != res[pos_cadena]:
                es_valido = False
                break

        if es_valido:
            return True

    return False

