def solucion(n):
	sw=0
	while n>100:
		arr=int(math.log10(n))+1
		s=0
		while n!=0:
		   d=n//10**(arr-1)
		   n=n%10**(arr-1)
		   arr=arr-1
		   res=n//10**(arr-1)
		   if arr!=0:
		   	if d+res>=10:
		   		s=s*10+((d+res)%10)
		   	else:
		   		s=s*10+(d+res)
		n=s
	return n

