def index(n):
    # Los números menores o iguales a 1 no son primos
    if n <= 1:
        return False
    # 2 y 3 son primos
    if n <= 3:
        return True
    # Descarta múltiplos de 2 y 3
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True


